INSERT INTO `tasks` (id,type,duration,duration_code,title,description,reward_text,reward_id_list,cash_reward,exp_reward,reward_method,reward_points,reward_point_type,min_level,max_level,level_spread,min_players,max_players,repeatable,faction_reward,completion_emote,replay_timer_group,replay_timer_seconds,request_timer_group,request_timer_seconds,dz_template_id,lock_activity_id,faction_amount,enabled) VALUES
(301200,1,21600,0,'The Bloodmoon','Slip into Bloodmoon Keep, thin the wolf and orc garrison, and strip five equipment crates of their harnesses for Larquin.','Experience',79705,0,250000,0,0,0,70,0,0,1,6,0,1191,'',0,0,0,0,6150,-1,40,1),
(301201,1,21600,0,'Walking into Spider Webs','Destroy the spider nursery in the northeast of Bloodmoon Keep and cull its brood.','Experience',79706,0,250000,0,0,0,70,0,0,1,6,0,1191,'',0,0,0,0,6151,-1,20,1),
(301202,1,21600,0,'Bronzebeard\'s Fate','Free the Bloodmoon slaves with jailor keys, then face what Hurley Bronzebeard has become.','Experience',79707,0,250000,0,0,0,70,0,0,1,6,0,1191,'',0,0,0,0,6152,-1,20,1),
(301203,1,21600,0,'The Departed','Cut through Bloodmoon\'s departed to the Spirit of Falstaff and put the old ghost to rest for Maria Starforge.','Experience',79708,0,250000,0,0,0,70,0,0,1,6,0,1191,'',0,0,0,0,6153,-1,40,1),
(301204,1,21600,0,'The Dark Crystals','Steal the Bloodmoon engineers\' charged crystals and sabotage their explosives cache for Maria Starforge.','Experience',79709,0,250000,0,0,0,70,0,0,1,6,0,1191,'',0,0,0,0,6154,-1,40,1),
(301205,1,21600,0,'Moonfang','Clear Bloodmoon Keep of its garrison before rousing Moonfang in the stables.','Experience',79703,0,250000,0,0,0,70,0,0,1,12,0,1191,'',0,0,0,0,6155,-1,40,1),
(301206,1,21600,0,'The Broodmother','Descend into the spider dens and destroy the Broodmother.','Experience',79704,0,250000,0,0,0,70,0,0,1,12,0,1191,'',0,0,0,0,6156,-1,40,1);
